        this.corrects = corrects;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getListed() {
        return listed;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    public int getProofs() {
        return proofs;
    }

    /** Add a proof: the proofs count is raised by one. */
    public void addProof() {
        proofs++;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectsDate() {
        return correctsDate;
    }

    public void setCorrectsDate(LocalDate correctsDate) {
        this.correctsDate = correctsDate;
    }

    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
    public LocalDate getRoundsBy() {
        return correctsDate != null ? correctsDate : date;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public List<ClaimLogLine> getLog() {
        return List.copyOf(log);
    }

    /** Log the status the claim has now, by a user on a date, with its due then. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogLine(status, by, on, due));
    }

    public List<ClaimComment> getComments() {
        return List.copyOf(comments);
    }

    /** Add a comment by a user on a date. */
    public void comment(String by, LocalDate on, String text) {
        comments.add(new ClaimComment(by, on, text));
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }

    /** Number the claim within a period sequence, shown as {@code label}. */
    public void setPeriodNumber(String sequence, int n, String label) {
        this.periodSequence = sequence;
        this.periodSeqNumber = n;
        this.periodNumber = label;
    }

    public String getPeriodSequence() {
        return periodSequence;
    }

    public Integer getPeriodSeqNumber() {
        return periodSeqNumber;
    }

    /** The number as shown: its period number, or its sheet-wide number; null while it has none. */
    public String getShownNumber() {
        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags == null ? "" : tags;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (a statement it counts at). */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Release the claim to its live figure (a statement it does not count at). */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.rate.Grades;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rate.RateTable;

/** The due figures of claims and the due-total of a person's claims. */
public final class Dues {

    private Dues() {
    }

    /**
     * A claim's due: once settled, the due fixed then (its late charge frozen in); a correction, its
     * {@link #base} figure (no floor, no late charge); otherwise the greater of the floor in force on its date
     * and its {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge} on that
     * figure. Null when there is none.
     */
    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal base = base(claim, grades, rates);
        if (base == null || claim.isCorrection()) {
            return base;
        }
        BigDecimal due = overdue(claim, grades, rates)
                ? base.add(rates.lateCharge(base, graceBy(claim, grades, rates), claim.getRoundsBy()))
                : base;
        return rates.floored(due, claim.getDate());
    }

    /**
     * A claim's figure before any late charge or floor: while bound by a statement (and not PENDING, which is
     * never bound), the figure bound then; otherwise its {@link #rateFigure rate figure}. Null when there is
     * none. A statement binds this figure, never the late charge or the floor.
     */
    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
        if (bound(claim)) {
            return claim.getStatedDue();
        }
        return rateFigure(claim, grades, rates);
    }

    /**
     * The amount at the rate in force on the claim's date for its person's grade in force then, rounded by
     * its date (a correction by the date its rounding goes by), see {@link RateTable#rounding}; no floor. Null when no rate is.
     */
    private static BigDecimal rateFigure(Claim claim, Grades grades, RateTable rates) {
        String grade = grades.on(claim.getDate());
        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
                rates.rounding(claim.getRoundsBy()))
                : rates.figure(claim.getAmount(), grade, claim.getDate());
    }

    /**
     * The figure the claim would have today as an OPEN claim bound by no statement: its rate figure plus the
     * late charge it has today on that figure when its due-by plus its grace has passed, but at least the floor in force on
     * its date; a correction has neither floor nor late charge. Null when there is none. Re-settling a claim
     * fixes its due at this figure.
     */
    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
        BigDecimal base = rateFigure(claim, grades, rates);
        if (base == null || claim.isCorrection()) {
            return base;
        }
        LocalDate graceBy = graceBy(claim, grades, rates);
        BigDecimal due = graceBy.isBefore(rates.today())
                ? base.add(rates.lateCharge(base, graceBy, claim.getRoundsBy()))
                : base;
        return rates.floored(due, claim.getDate());
    }

    /** Whether a statement binds the claim's figure: it is stated and not PENDING. */
    public static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /**
     * Whether the claim is overdue: OPEN or PENDING, not {@link #deferred deferred}, and due by a date before
     * the sheet's today (its due-by, fixed when it was added, plus its {@link #graceBy grace}).
     */
    public static boolean overdue(Claim claim, Grades grades, RateTable rates) {
        return claim.getStatus().unpaid() && !deferred(claim, rates.today())
                && graceBy(claim, grades, rates).isBefore(rates.today());
    }

    /**
     * The date a claim's overdue and late charge count from: its due-by plus the grace days in force on its
     * date for its person's grade in force then (none: its due-by). The due-by shown is unchanged.
     */
    public static LocalDate graceBy(Claim claim, Grades grades, RateTable rates) {
        return claim.getDueBy().plusDays(rates.settings().grace(grades.on(claim.getDate()), claim.getDate()));
    }

    /** Whether the claim is deferred on the given today: OPEN and deferred until a date after it. */
    public static boolean deferred(Claim claim, LocalDate today) {
        return claim.getStatus() == ClaimStatus.OPEN && claim.getDeferredUntil() != null
                && today.isBefore(claim.getDeferredUntil());
    }

    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
    public static List<Claim> overdue(List<Claim> claims, Grades grades, RateTable rates, Holds holds) {
        return claims.stream().filter(c -> counts(c, holds, rates.today()) && overdue(c, grades, rates)).toList();
    }

    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
    private static boolean kept(Claim claim) {
        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
    }

    /**
     * Whether the claim counts in the live totals on the sheet's today: OPEN, PENDING and SETTLED claims do,
     * except that an OPEN claim dated within one of its person's holds, and an OPEN or PENDING claim of a
     * person whose retirement date that today has reached, counts in none, unless a statement binds it, and a claim {@link #deferred deferred} on that today counts in none.
     */
    public static boolean counts(Claim claim, Holds holds, LocalDate today) {
        return claim.getStatus().counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
    }

    /**
     * Whether the person's holds or retirement leave the claim out of the live totals: unless a statement
     * binds it, an OPEN claim dated within a hold, and an OPEN or PENDING claim once the sheet's today has
     * reached the person's retirement date.
     */
    private static boolean leftOut(Claim claim, Holds holds, LocalDate today) {
        return !bound(claim) && ((claim.getStatus() == ClaimStatus.OPEN && holds.on(claim.getDate()))
                || (claim.getStatus().unpaid() && holds.retiredOn(today)));
    }

    /**
     * Whether the person is active on the sheet's today: they have an OPEN or PENDING claim that counts (see
     * {@link #counts}) dated within the 30 days up to and including that today.
     */
    public static boolean active(List<Claim> claims, Holds holds, LocalDate today) {
        LocalDate from = today.minusDays(29);
        return claims.stream().anyMatch(c -> (c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                && counts(c, holds, today) && !c.getDate().isBefore(from) && !c.getDate().isAfter(today));
    }

    /**
     * The sum of the due figures of the OPEN and PENDING claims that count (see {@link #counts}) whose age on
     * the sheet's today (the days from the claim's date; a claim dated after that today is aged 0) is from
     * {@code fromDays} to {@code toDays} inclusive (0.00 with none); a claim with no figure is skipped.
     */
    public static BigDecimal aged(Grades grades, List<Claim> claims, RateTable rates, Holds holds, long fromDays,
            long toDays) {
        LocalDate today = rates.today();
        return sum(grades, claims.stream().filter(c -> c.getStatus().unpaid() && counts(c, holds, today))
                .filter(c -> {
                    long age = Math.max(0, ChronoUnit.DAYS.between(c.getDate(), today));
                    return age >= fromDays && age <= toDays;
                }).toList(), rates);
    }

    /**
     * The sum of the settled figures of the SETTLED claims dated within the 90 days up to and including the
     * sheet's today, each at the figure frozen when it was settled (0.00 with none); one with none is skipped.
     */
    public static BigDecimal recentSettled(List<Claim> claims, LocalDate today) {
        LocalDate from = today.minusDays(89);
        return claims.stream().filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null
                && !c.getDate().isBefore(from) && !c.getDate().isAfter(today)).map(Claim::getSettledDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /**
     * The status the claim had at the end of the given day, as its status log records it (each line on the
     * sheet's today then); null when it was added after that day.
     */
    public static ClaimStatus statusAsOf(Claim claim, LocalDate day) {
        ClaimStatus status = null;
        for (ClaimLogLine line : claim.getLog()) {
            if (!line.getOn().isAfter(day)) {
                status = line.getStatus();
            }
        }
        return status;
    }

    /**
     * Whether the claim counts in a period ending on {@code end}: its status at the end of that day (see
     * {@link #statusAsOf}) is OPEN, PENDING or SETTLED, and it is neither left out by a hold nor deferred on the
     * sheet's today, as in {@link #counts}; so too by a retirement reached on that today.
     */
    public static boolean countsAsOf(Claim claim, Holds holds, LocalDate today, LocalDate end) {
        ClaimStatus then = statusAsOf(claim, end);
        return then != null && then.counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
    }

    /**
     * A person's due-total (see {@link #total}); a person not on hold.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
        return total(grades, claims, rates, Holds.NONE);
    }

    /**
     * A person's due-total: their {@link #uncapped} sum held to the sheet's cap, see {@link RateTable#capped}.
     * Null (n/a) when the sum is.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return rates.capped(uncapped(grades, claims, rates, holds));
    }

    /** What a person's {@link #uncapped} sum is above the sheet's cap: 0.00 when it is not, or is n/a. */
    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return rates.excess(uncapped(grades, claims, rates, holds));
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
     * is the sum of the figures there are; so too when that grade's rate has ended by the sheet's today and
     * a claim that counts has a figure.
     */
    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        List<Claim> counting = claims.stream().filter(c -> counts(c, holds, rates.today())).toList();
        String current = grades.on(rates.today());
        boolean ended = rates.ended(current, rates.today());
        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
                || ((ended || !current.equals(grades.on(c.getDate()))) && figure(c, grades, rates) != null));
        return shown ? counting.stream().map(c -> figure(c, grades, rates))
                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
    }

    /**
     * The settled part of a person's {@link #uncapped} sum: the due figures of their SETTLED claims that count,
     * each at its frozen figure (corrections included); a claim with no figure is skipped.
     */
    public static BigDecimal settledTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return part(grades, claims, rates, holds, true);
    }

    /**
     * The open part of a person's {@link #uncapped} sum: the due figures of their OPEN and PENDING claims that
     * count (a held, deferred or retired-and-left-out claim does not); a claim with no figure is skipped.
     */
    public static BigDecimal openTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return part(grades, claims, rates, holds, false);
    }

    private static BigDecimal part(Grades grades, List<Claim> claims, RateTable rates, Holds holds, boolean settled) {
        return sum(grades, claims.stream().filter(c -> counts(c, holds, rates.today())
                && (c.getStatus() == ClaimStatus.SETTLED) == settled).toList(), rates);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID), and a
 * steward may void a SETTLED one within 7 days of its settlement. Only OPEN, PENDING and SETTLED claims count
 * toward what is claimed.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether the claim counts toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still to be paid: OPEN or PENDING. */
    public boolean unpaid() {
        return this == OPEN || this == PENDING;
    }

    /**
     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
     * PENDING claim leaves PENDING only by being approved, rejected or voided.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DRAFT -> false;
        };
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** Whether a person is on hold on a date, and whether they are retired on a sheet's today. */
@FunctionalInterface
public interface Holds {

    /** No hold on any date. */
    Holds NONE = date -> false;

    /** Whether a hold covers the date. */
    boolean on(LocalDate date);

    /** Whether the person's retirement date is reached on the sheet's today; never, unless said otherwise. */
    default boolean retiredOn(LocalDate today) {
        return false;
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Permission;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.TodayChanged;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.event.EventListener;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims on a sheet: listed per person newest first, added, edited and moved through their
 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
 * its number, which is never reused; a claim opened while period numbering is on is numbered within its
 * period instead of sheet-wide. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
 * (at least the sheet's floor then), or at the
 * figure a statement bound it to, plus the late charge it has then. A claim belongs to the period containing its due-by
 * (fixed when it was added, moved past the sheet's holidays then); no claim due by a date inside a closed period can be added, edited or moved,
 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
 * settling a claim whose due is above the sheet's clerk limit leaves it PENDING instead; a steward settles
 * anything, and approves a PENDING claim (settling it, its due fixed then) or rejects it with a reason
 * (back to OPEN); neither the user who opened a claim nor the one who last edited it can settle or approve it. A steward re-settles a SETTLED claim,
 * fixing its due again at the figure it would have today as an OPEN claim bound by no statement. A claim
 * with a negative amount is a correction: it is added or edited only when it names, by number, a SETTLED
 * claim of the same person, and only a correction names one. A claim whose due is above the sheet's proof
 * threshold in force on its date cannot be settled or approved while it has no proof.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final RateService rates;
    private final Rollup rollup;
    private final PeriodService periods;
    private final AccessService access;
    private final WatchService watches;
    private final HolidayService holidays;
    private final Tags tags;
    private final VoidReasons voidReasons;
    private final ApplicationEventPublisher events;

    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
            SheetRepository sheetRows, RateService rates, Rollup rollup, PeriodService periods, AccessService access,
            WatchService watches, HolidayService holidays, Tags tags, VoidReasons voidReasons,
            ApplicationEventPublisher events) {
        this.tags = tags;
        this.voidReasons = voidReasons;
        this.holidays = holidays;
        this.access = access;
        this.watches = watches;
        this.rollup = rollup;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.rates = rates;
        this.events = events;
    }

    /** Every claim on the sheet by the person who made it, each person's newest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<Claim>> bySheet(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
    }

    @Transactional(readOnly = true)
    public List<Claim> forPerson(String sheetId, long personId) {
        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
    }

    /** Add a claim; a date left out takes the sheet's entry date while set, else its today. Returns the person it belongs to. */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    /**
     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
     * sheet's entry date while set, else its today. Returns the person it belongs to.
     */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    /**
     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String)} does, carrying an
     * external reference (surrounding spaces removed; blank: none), refused when a claim on the sheet already
     * carries it, compared without regard to case. Returns the person it belongs to.
     */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /**
     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)} does,
     * carrying the tags in the comma separated text (see {@link Tags#normalize}; null: none). Returns the
     * person it belongs to.
     */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tagText) {
        String tagged = Tags.normalize(tagText);
        String reference = requireFreeRef(sheetId, ref, null);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = date != null ? date : sheets.claimDate(sheetId);
        sheets.load(sheetId, user);
        int terms = sheets.settings(sheetId).termsFor(person.getTerms(), person.gradeOn(on), on);
        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
        periods.requireOpen(sheetId, dueBy);
        requireNotRetired(person, on);
        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
        Rollup.Figures before = rollup.figures(sheetId);
        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
        claim.setCorrectsDate(correctsDate);
        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy).isPresent());
        claim.setDueBy(dueBy);
        claim.setTerms(terms);
        claim.setRef(reference);
        claim.setTags(tagged);
        log(sheetId, user, claim, person);
        claims.saveAndFlush(claim);
        tags.use(sheetId, tagged);
        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null,
                null, null, reference, tagged.isEmpty() ? null : tagged));
        if (claim.isLateEntry()) {
            events.publishEvent(new ClaimChanged("LATE_ENTRY", sheetId, user, person.getName(), amount, on, null, null));
        }
        rollup.changed(sheetId, user, before);
        return personId;
    }

    /**
     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
     * added again instead), and an edit is refused when a closed period contains its due-by (which an edit
     * leaves as it was fixed), or
     * when the date it is left with is after its person's retirement date, or when its external reference
     * (surrounding spaces removed; blank: none) is carried by another claim on the sheet, compared without
     * regard to case. Its tags are those in the comma separated text (see {@link Tags#normalize}; null: none).
     * Returns the person it belongs to.
     */
    @Transactional
    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tagText) {
        String tagged = Tags.normalize(tagText);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        String reference = requireFreeRef(sheetId, ref, claimId);
        LocalDate on = date != null ? date : sheets.today(sheetId);
        periods.requireOpen(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
        }
        requireNotLockedByOther(claim, user);
        people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
        Rollup.Figures before = rollup.figures(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setCorrectsDate(correctsDate);
        claim.setDate(on);
        claim.setNote(note == null ? "" : note);
        claim.setRef(reference);
        claim.setTags(tagged);
        claim.setLockedBy(null);
        claim.setEditedBy(user);
        claims.flush();
        tags.use(sheetId, tagged);
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
                claim.getDate(), claim.getShownNumber(), null));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Change a claim's amount alone, keeping its date, note and the claim it corrects; refused exactly as
     * an {@link #edit} with that amount is. Returns the person it belongs to.
     */
    @Transactional
    public long editAmount(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claim(sheetId, claimId);
        return edit(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
                claim.getRef(), claim.getTags());
    }

    /**
     * An external reference with its surrounding spaces removed, or null when blank; refused when a claim on
     * the sheet other than {@code claimId} (null: any claim) carries it, compared without regard to case.
     */
    String requireFreeRef(String sheetId, String ref, Long claimId) {
        String reference = ref == null || ref.isBlank() ? null : ref.strip();
        if (reference != null && (claimId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)
                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, claimId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The reference \"" + reference + "\" is already used on the sheet");
        }
        return reference;
    }

    /**
     * Open a claim's editor, locking the claim for every other user until the editor is saved or cancelled
     * or the sheet's today changes. Only a DRAFT due by a date outside every closed period can be edited, and a claim
     * another user's editor holds is refused; a refusal takes no lock. No audit line. Returns the person
     * it belongs to.
     */
    @Transactional
    public long lock(String sheetId, String user, long claimId) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
        }
        requireNotLockedByOther(claim, user);
        claim.setLockedBy(user);
        claims.flush();
        return claim.getPersonId();
    }

    /** Cancel a claim's editor, releasing the user's lock on it; another user's lock stays. Returns the person. */
    @Transactional
    public long unlock(String sheetId, String user, long claimId) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        if (user.equals(claim.getLockedBy())) {
            claim.setLockedBy(null);
            claims.flush();
        }
        return claim.getPersonId();
    }

    /** A change of the sheet's today releases every editor's lock on its claims. */
    @EventListener
    @Transactional
    public void on(TodayChanged e) {
        claims.findBySheetIdAndLockedByIsNotNull(e.sheetId()).forEach(c -> c.setLockedBy(null));
        claims.flush();
    }

    private static void requireNotLockedByOther(Claim claim, String user) {
        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim is being edited by " + claim.getLockedBy());
        }
    }

    /**
     * Move a claim to a status; a move its status does not allow, opening, settling or voiding by a role the
     * sheet's permission matrix does not allow, settling by the user who opened
     * the claim, or moving a claim due by a date inside a closed period, is refused and changes nothing. Settling
     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
     * Returns the person it belongs to.
     */
    @Transactional
    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
        return move(sheetId, user, claimId, next, null);
    }

    /**
     * Number a bulk settle that settled the claims (to SETTLED or PENDING) as the sheet's next settle batch,
     * each claim showing it, and record it with the frozen figures of those SETTLED added up. Returns the
     * batch number.
     */
    @Transactional
    public int settleBatch(String sheetId, String user, List<Long> claimIds) {
        int batch = sheets.nextSettleBatch(sheetId);
        BigDecimal total = BigDecimal.ZERO;
        for (long id : claimIds) {
            Claim claim = claim(sheetId, id);
            claim.setSettleBatch(batch);
            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
                total = total.add(claim.getSettledDue());
            }
        }
        claims.flush();
        events.publishEvent(new BatchSettled(sheetId, user, batch, claimIds.size(), total));
        return batch;
    }

    /** The number of the sheet's last settle batch; 0 when there has been none. */
    public int lastSettleBatch(String sheetId) {
        return sheets.lastSettleBatch(sheetId);
    }

    /**
     * Move a claim to a status as {@link #move(String, String, long, ClaimStatus)}; a claim is voided with the
     * given reason, which while the sheet's list of void reasons is not empty must be on it, else the void is
     * refused (see {@link VoidReasons#require}).
     */
    @Transactional
    public long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
        Claim claim = claim(sheetId, claimId);
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        Permission permission = switch (next) {
            case OPEN -> Permission.OPEN;
            case SETTLED -> Permission.SETTLE;
            case VOID -> Permission.VOID;
            default -> null;
        };
        if (permission != null && !access.allows(sheetId, user, permission)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Your role may not " + permission.action() + " a claim on this sheet");
        }
        String reasonGiven = next == ClaimStatus.VOID ? voidReasons.require(sheetId, voidReason) : null;
        String reversed = null;
        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            requireVoidableSettled(sheetId, user, claim);
            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
        }
        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who last edited a claim cannot settle it");
        }
        if (next == ClaimStatus.OPEN) {
            requireNote(sheetId, claim);
        }
        Rollup.Figures before = rollup.figures(sheetId);
        if (next == ClaimStatus.OPEN) {
            giveNumber(sheetId, claim);
            claim.setOpenedBy(user);
        }
        String number = claim.getShownNumber();
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
        String due = null;
        if (next == ClaimStatus.SETTLED) {
            BigDecimal fixed = dueNow(sheetId, claim, owner);
            requireProof(sheetId, claim, owner, fixed);
            if (access.canSettle(sheetId, user, fixed)) {
                claim.setSettledDue(fixed);
                due = fixed == null ? "n/a" : fixed.toPlainString();
            } else {
                next = ClaimStatus.PENDING;
            }
        }
        claim.setStatus(next);
        if (next == ClaimStatus.VOID) {
            claim.setVoidReason(reasonGiven);
        }
        log(sheetId, user, claim, owner);
        claims.flush();
        String person = owner == null ? "" : owner.getName();
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
                due, null, reversed, null, null, reasonGiven));
        if (next == ClaimStatus.SETTLED) {
            watches.notifyWatchers(sheetId, user, owner, number);
        }
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim due by a date inside a closed
     * period is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
        }
        LocalDate today = sheets.today(sheetId);
        if (!until.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        claim.setDeferredUntil(until);
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), until));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement
     * bound it to stays bound; so does its period (the one containing its due-by) and its number. A claim
     * not OPEN or PENDING, one due by a date inside a closed period, a new date after its person's
     * retirement date, or a re-date by
     * anyone but a steward is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long redate(String sheetId, String user, long claimId, LocalDate date) {
        Claim claim = claim(sheetId, claimId);
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-date a claim");
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
        }
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        requireNotRetired(owner, date);
        Rollup.Figures before = rollup.figures(sheetId);
        LocalDate old = claim.getDate();
        claim.setDate(date);
        claims.flush();
        events.publishEvent(new ClaimRedated(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), old, date));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps
     * the rest and is released from any figure a statement bound it to; a new OPEN claim of the same person
     * takes the amount split off, with the same date and note, the next number, opened by the user and
     * due by its date plus the terms then of its person's grade on its date, naming the claim it was split
     * from, carrying its tags, and a late entry when that claim is. It is judged by the claim split alone: a claim not OPEN, a deferred one, one due by a date inside a closed period, an amount out of range, or a
     * split by a role the sheet's permission matrix does not allow to open a claim is refused and nothing
     * changes. Returns the person it belongs to.
     */
    @Transactional
    public long split(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
        }
        if (Dues.deferred(claim, sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
        }
        if (!access.allows(sheetId, user, Permission.OPEN)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
        }
        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
        }
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Rollup.Figures before = rollup.figures(sheetId);
        claim.setAmount(claim.getAmount().subtract(amount));
        claim.unbind();
        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
        sheets.load(sheetId, user);
        int terms = sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate());
        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
        part.setTerms(terms);
        part.setSplitFrom(claim.getShownNumber());
        part.setTags(claim.getTags());
        part.setLateEntry(claim.isLateEntry());
        giveNumber(sheetId, part);
        part.setOpenedBy(user);
        part.setStatus(ClaimStatus.OPEN);
        log(sheetId, user, part, owner);
        claims.saveAndFlush(part);
        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), part.getShownNumber()));
        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
                part.getDate(), part.getShownNumber(), null));
        rollup.changed(sheetId, user, before);
        return owner.getId();
    }

    /**
     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long addProof(String sheetId, String user, long claimId) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot take a proof");
        }
        claim.addProof();
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), claim.getProofs()));
        return claim.getPersonId();
    }

    /**
     * Comment a claim, in any status: the comment is kept with the user and the sheet's today. A blank
     * comment is refused and nothing changes. Returns the person it belongs to.
     */
