447	        claim.setDate(date);
448	        claims.flush();
449	        events.publishEvent(new ClaimRedated(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
450	                claim.getShownNumber(), old, date));
451	        rollup.changed(sheetId, user, before);
452	        return claim.getPersonId();
453	    }
454	
455	    /**
456	     * Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps
457	     * the rest and is released from any figure a statement bound it to; a new OPEN claim of the same person
458	     * takes the amount split off, with the same date and note, the next number, opened by the user and
459	     * due by its date plus the terms then of its person's grade on its date, naming the claim it was split
460	     * from, carrying its tags, and a late entry when that claim is. It is judged by the claim split alone: a claim not OPEN, a deferred one, one due by a date inside a closed period, an amount out of range, or a
461	     * split by a role the sheet's permission matrix does not allow to open a claim is refused and nothing
462	     * changes. Returns the person it belongs to.
463	     */
464	    @Transactional
465	    public long split(String sheetId, String user, long claimId, BigDecimal amount) {
466	        Claim claim = claim(sheetId, claimId);
467	        if (claim.getStatus() != ClaimStatus.OPEN) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT,
469	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
470	        }
471	        if (Dues.deferred(claim, sheets.today(sheetId))) {
472	            throw new ResponseStatusException(HttpStatus.CONFLICT,
473	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
474	        }
475	        if (!access.allows(sheetId, user, Permission.OPEN)) {
476	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
477	        }
478	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
479	            throw new ResponseStatusException(HttpStatus.CONFLICT,
480	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
481	        }
482	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
483	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
484	        Rollup.Figures before = rollup.figures(sheetId);
485	        claim.setAmount(claim.getAmount().subtract(amount));
486	        claim.unbind();
487	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
488	        sheets.load(sheetId, user);
489	        int terms = sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate());
490	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
491	        part.setTerms(terms);
492	        part.setSplitFrom(claim.getShownNumber());
493	        part.setTags(claim.getTags());
494	        part.setLateEntry(claim.isLateEntry());
495	        giveNumber(sheetId, part);
496	        part.setOpenedBy(user);
497	        part.setStatus(ClaimStatus.OPEN);
498	        log(sheetId, user, part, owner);
499	        claims.saveAndFlush(part);
500	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
501	                claim.getShownNumber(), part.getShownNumber()));
502	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
503	                part.getDate(), part.getShownNumber(), null));
504	        rollup.changed(sheetId, user, before);
505	        return owner.getId();
506	    }
507	
508	    /**
509	     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
510	     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
511	     */
512	    @Transactional
513	    public long addProof(String sheetId, String user, long claimId) {
514	        Claim claim = claim(sheetId, claimId);
515	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
516	            throw new ResponseStatusException(HttpStatus.CONFLICT,
517	                    "A " + claim.getStatus() + " claim cannot take a proof");
518	        }
519	        claim.addProof();
520	        claims.flush();
521	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
522	        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
523	                claim.getShownNumber(), claim.getProofs()));
524	        return claim.getPersonId();
525	    }
526	
527	    /**
528	     * Comment a claim, in any status: the comment is kept with the user and the sheet's today. A blank
529	     * comment is refused and nothing changes. Returns the person it belongs to.
530	     */
531	    @Transactional
532	    public long comment(String sheetId, String user, long claimId, String text) {
533	        if (text == null || text.isBlank()) {
534	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty");
535	        }
536	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
537	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
538	        String comment = text.trim();
539	        claim.comment(user, sheets.today(sheetId), comment);
540	        claims.flush();
541	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
542	        events.publishEvent(new ClaimCommented(sheetId, user, person, claim.getAmount(), claim.getDate(),
543	                claim.getShownNumber(), comment));
544	        return claim.getPersonId();
545	    }
546	
547	    /**
548	     * Remind an OPEN or PENDING claim: it takes the sheet's today as its reminded date. A claim can be
549	     * reminded once per sheet's today; a claim in any other status, one already reminded on the sheet's today,
550	     * or a claim due by a date inside a closed period is refused and nothing changes. Returns the person it
551	     * belongs to.
552	     */
553	    @Transactional
554	    public long remind(String sheetId, String user, long claimId) {
555	        Claim claim = claim(sheetId, claimId);
556	        if (!claim.getStatus().unpaid()) {
557	            throw new ResponseStatusException(HttpStatus.CONFLICT,
558	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
559	        }
560	        LocalDate today = sheets.today(sheetId);
561	        if (today.equals(claim.getRemindedOn())) {
562	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today (" + today + ")");
563	        }
564	        claim.setRemindedOn(today);
565	        claims.flush();
566	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
567	        events.publishEvent(new ClaimReminded(sheetId, user, person, claim.getAmount(), claim.getDate(),
568	                claim.getShownNumber()));
569	        return claim.getPersonId();
570	    }
571	
572	    /**
573	     * Refuse opening a claim with an empty note whose due (null: n/a) is above the sheet's note threshold in
574	     * force on the claim's date.
575	     */
576	    private void requireNote(String sheetId, Claim claim) {
577	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
578	            return;
579	        }
580	        BigDecimal threshold = sheets.settings(sheetId).noteThreshold(claim.getDate());
581	        if (threshold == null) {
582	            return;
583	        }
584	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
585	        BigDecimal due = dueNow(sheetId, claim, owner);
586	        if (due != null && due.compareTo(threshold) > 0) {
587	            throw new ResponseStatusException(HttpStatus.CONFLICT,
588	                    "A claim with a due above " + threshold.toPlainString() + " needs a note to be opened");
589	        }
590	    }
591	
592	    /**
593	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the proof threshold
594	     * in force on the claim's date: its owner's grade's then when one is set, else the sheet's.
595	     */
596	    private void requireProof(String sheetId, Claim claim, Person owner, BigDecimal due) {
597	        if (due == null || claim.getProofs() > 0) {
598	            return;
599	        }
600	        String grade = owner == null ? null : owner.gradeOn(claim.getDate());
601	        BigDecimal threshold = sheets.settings(sheetId).proofThresholdFor(grade, claim.getDate());
602	        if (threshold != null && due.compareTo(threshold) > 0) {
603	            throw new ResponseStatusException(HttpStatus.CONFLICT,
604	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
605	        }
606	    }
607	
608	    /**
609	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
610	     * Only a steward approves, never the user who opened the claim or last edited it; a claim not PENDING or due by a date inside a
611	     * closed period is refused and nothing changes. Returns the person it belongs to.
612	     */
613	    @Transactional
614	    public long approve(String sheetId, String user, long claimId) {
615	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
616	        if (user.equals(claim.getOpenedBy())) {
617	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
618	        }
619	        if (user.equals(claim.getEditedBy())) {
620	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
621	                    "The user who last edited a claim cannot approve it");
622	        }
623	        Rollup.Figures before = rollup.figures(sheetId);
624	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
625	        BigDecimal fixed = dueNow(sheetId, claim, owner);
626	        requireProof(sheetId, claim, owner, fixed);
627	        claim.setSettledDue(fixed);
628	        claim.setStatus(ClaimStatus.SETTLED);
629	        log(sheetId, user, claim, owner);
630	        claims.flush();
631	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
632	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
633	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
634	        rollup.changed(sheetId, user, before);
635	        return claim.getPersonId();
636	    }
637	
638	    /**
639	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
640	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
641	     * steward re-settles; a claim not SETTLED or due by a date inside a closed period is refused and nothing changes.
642	     * Returns the person it belongs to.
643	     */
644	    @Transactional
645	    public long resettle(String sheetId, String user, long claimId) {
646	        Claim claim = claim(sheetId, claimId);
647	        if (claim.getStatus() != ClaimStatus.SETTLED) {
648	            throw new ResponseStatusException(HttpStatus.CONFLICT,
649	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
650	        }
651	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
652	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
653	        }
654	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
655	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
656	        Rollup.Figures before = rollup.figures(sheetId);
657	        BigDecimal old = claim.getSettledDue();
658	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
659	        claim.setSettledDue(fixed);
660	        claim.logStatus(user, sheets.today(sheetId), fixed);
661	        claims.flush();
662	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
663	                claim.getShownNumber(), old, fixed));
664	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
665	        rollup.changed(sheetId, user, before);
666	        return claim.getPersonId();
667	    }
668	
669	    /**
670	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
671	     * that statement counted it). Only a steward rejects; a claim not PENDING or due by a date inside a closed
672	     * period is refused and nothing changes. Returns the person it belongs to.
673	     */
674	    @Transactional
675	    public long reject(String sheetId, String user, long claimId, String reason) {
676	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
677	        Rollup.Figures before = rollup.figures(sheetId);
678	        claim.setStatus(ClaimStatus.OPEN);
679	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
680	        log(sheetId, user, claim, owner);
681	        claims.flush();
682	        String person = owner == null ? "" : owner.getName();
683	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
684	                claim.getDate(), claim.getShownNumber(), null, reason));
685	        rollup.changed(sheetId, user, before);
686	        return claim.getPersonId();
687	    }
688	
689	    /**
690	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
691	     * number and date, is released from any figure a statement bound it to (live again until its new
692	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
693	     * correction, a claim due by a date inside a closed period or after the new person's retirement date, or a move
694	     * by a role the sheet's permission matrix does not allow (a steward, unless set) is refused and nothing changes. Returns the people it moved from and to.
695	     */
696	    @Transactional
697	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
698	        return reassign(sheetId, user, claimId, toPersonId, false);
699	    }
700	
701	    /**
702	     * As {@link #reassign(String, String, long, long)}; when {@code sameAllowed}, a claim already the new
703	     * person's is moved to them again (listed as their newest claim) rather than refused, as a bulk move does.
704	     */
705	    @Transactional
706	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId, boolean sameAllowed) {
707	        Claim claim = claim(sheetId, claimId);
708	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
709	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
710	        }
711	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
712	                && claim.getStatus() != ClaimStatus.PENDING) {
713	            throw new ResponseStatusException(HttpStatus.CONFLICT,
714	                    "A " + claim.getStatus() + " claim cannot be reassigned");
715	        }
716	        if (claim.isCorrection()) {
717	            throw new ResponseStatusException(HttpStatus.CONFLICT,
718	                    "A correction belongs with the claim it corrects and cannot be reassigned");
719	        }
720	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
721	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
722	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
723	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
724	        if (!sameAllowed && from.getId().equals(to.getId())) {
725	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
726	        }
727	        requireNotRetired(to, claim.getDate());
728	        Rollup.Figures before = rollup.figures(sheetId);
729	        claim.setPersonId(to.getId());
730	        claim.unbind();
731	        claims.flush();
732	        claims.relist(claim.getId());
733	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
734	                claim.getShownNumber(), from.getName(), to.getName()));
735	        rollup.changed(sheetId, user, before);
736	        return new long[] { from.getId(), to.getId() };
737	    }
738	
739	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
740	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
741	        Claim claim = claim(sheetId, claimId);
742	        if (claim.getStatus() != ClaimStatus.PENDING) {
743	            throw new ResponseStatusException(HttpStatus.CONFLICT,
744	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
745	        }
746	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
747	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
748	        }
749	        return claim;
750	    }
751	
752	    /**
753	     * A SETTLED claim may be voided only by a steward, and only while the sheet's today is no more than
754	     * 7 days after the date its status log records it SETTLED.
755	     */
756	    private void requireVoidableSettled(String sheetId, String user, Claim claim) {
757	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
758	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
759	        }
760	        LocalDate settledOn = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
761	                .map(ClaimLogLine::getOn).reduce((a, b) -> b).orElse(null);
762	        LocalDate today = sheets.today(sheetId);
763	        if (settledOn == null || today.isAfter(settledOn.plusDays(7))) {
764	            throw new ResponseStatusException(HttpStatus.CONFLICT,
765	                    "A SETTLED claim can only be voided within 7 days of its settlement"
766	                            + (settledOn == null ? "" : " (" + settledOn + ")"));
767	        }
768	    }
769	
770	    private Claim claim(String sheetId, long claimId) {
771	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
772	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
773	        periods.requireOpen(sheetId, claim.getDueBy());
774	        return claim;
775	    }
776	
777	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
778	    private void log(String sheetId, String user, Claim claim, Person owner) {
779	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
780	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
781	        claim.logStatus(user, sheets.today(sheetId), due);
782	    }
783	
784	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
785	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
786	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
787	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
788	    }
789	
790	    /**
791	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
792	     * sheet's today is on or after it, the next in the period its due-by falls in (<period name>-<n>), or
793	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
794	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
795	     */
796	    private void giveNumber(String sheetId, Claim claim) {
797	        if (!numberingOn(sheetId)) {
798	            claim.setNumber(sheets.nextClaimNumber(sheetId));
799	            return;
800	        }
801	        sheetRows.lockById(sheetId);
802	        Period period = periodOf(sheetId, claim.getDueBy());
803	        String sequence = sequenceOf(sheetId, claim.getDueBy());
804	        int n = claims.lastInSequence(sheetId, sequence) + 1;
805	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
806	    }
807	
808	    /** Whether the sheet's period numbering from is set and the sheet's today is on or after it. */
809	    private boolean numberingOn(String sheetId) {
810	        LocalDate from = sheets.periodNumberingFrom(sheetId);
811	        return from != null && !sheets.today(sheetId).isBefore(from);
812	    }
813	
814	    /** The period whose dates contain the date, or null when none does. */
815	    private Period periodOf(String sheetId, LocalDate date) {
816	        return periods.list(sheetId).stream().filter(p -> p.contains(date)).findFirst().orElse(null);
817	    }
818	
819	    /** The period sequence a claim due by the date counts in ('P<period id>', or 'X' for no period). */
820	    private String sequenceOf(String sheetId, LocalDate date) {
821	        Period period = periodOf(sheetId, date);
822	        return period == null ? "X" : "P" + period.getId();
823	    }
824	
825	    /**
826	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
827	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
828	     * correction corrects (its rounding goes by it); null for any other claim.
829	     */
830	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
831	        if (amount.signum() >= 0) {
832	            if (corrects != null) {
833	                throw new ResponseStatusException(HttpStatus.CONFLICT,
834	                        "Only a correction (a negative amount) names a claim it corrects");
835	            }
836	            return null;
837	        }
838	        if (corrects == null) {
839	            throw new ResponseStatusException(HttpStatus.CONFLICT,
840	                    "A negative amount is a correction; name the number of the settled claim it corrects");
841	        }
842	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
843	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
844	                .map(Claim::getDate).findFirst()
845	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
846	                        "Claim " + corrects + " is not a settled claim of this person"));
847	    }
848	
849	    /** Refuse a claim dated after its person's retirement date. */
850	    private static void requireNotRetired(Person person, LocalDate date) {
851	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
852	            throw new ResponseStatusException(HttpStatus.CONFLICT,
853	                    person.getName() + " is retired from " + person.getRetiredFrom()
854	                            + "; a claim cannot be dated after that");
855	        }
856	    }
857	}
