package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.DatedSettings;

/**
 * Every rate on a sheet, the sheet's today, its dated settings (the floor in force on a claim's date, the late
 * percent in force on each 30-day boundary past its due-by, the cap in force on the sheet's today) and its policy date (null: the sheet's today): which rate is in force for a grade on a date, the live due it
 * makes of an amount, the late charge an overdue figure gains, how a claim's figures round, and the most a
 * person's due-total comes to.
 */
public record RateTable(List<Rate> rates, LocalDate today, DatedSettings settings, LocalDate policyDate) {

    /** The days in each period overdue that adds the late percent once more. */
    private static final int LATE_PERIOD_DAYS = 30;

    /**
     * The percent in force for the grade on the date: the rate whose from-date is the latest one on
     * or before it, a rate with no from-date applying from the beginning of time; null when none does,
     * or when that rate's to-date is before the date (it has ended, and no later rate is in force).
     */
    public BigDecimal on(String grade, LocalDate date) {
        return latest(grade, date).filter(r -> !ended(r, date)).map(Rate::getPct).orElse(null);
    }

    /** Whether the grade has no rate on the date only because the rate that would apply has ended by then. */
    public boolean ended(String grade, LocalDate date) {
        return latest(grade, date).filter(r -> ended(r, date)).isPresent();
    }

    /** The grade's rate with the latest from-date on or before the date, ended or not. */
    private Optional<Rate> latest(String grade, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    private static boolean ended(Rate rate, LocalDate date) {
        return rate.getToDate() != null && rate.getToDate().isBefore(date);
    }

    /** The cap in force on the sheet's today: the most a person's due-total comes to; null when there is none. */
    public BigDecimal cap() {
        return settings.cap(today);
    }

    /** A due-total held to the cap: the cap when the sum is above it; as it is otherwise, or when n/a (null). */
    public BigDecimal capped(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? sum : cap;
    }

    /** What a due-total's sum is above the cap: 0.00 when it is not, or when n/a (null). */
    public BigDecimal excess(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? BigDecimal.ZERO : sum.subtract(cap);
    }

    /** The percent in force for the grade on the sheet's today; null when none is. */
    public BigDecimal current(String grade) {
        return on(grade, today);
    }

    /**
     * How the figures of a claim whose rounding goes by the date round: half up when it is before the
     * policy date (the sheet's today when none is set), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate roundsBy) {
        LocalDate policy = policyDate == null ? today : policyDate;
        return roundsBy.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The rate figure of an amount dated on the date for the grade: the amount at the rate in force then,
     * rounded by the date, with no floor; null when no rate is.
     */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date) {
        return RateService.due(amount, on(grade, date), rounding(date));
    }

    /** A live due held up to the floor in force on the date: the greater of the two; null when the due is. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        BigDecimal floor = settings.floor(date);
        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    }

    /**
     * The late charge on a figure of a claim due by the due-by: for every full 30 days from its due-by to the
     * sheet's today, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of
     * the figure plus the charges of the boundaries before it (compounding), each rounded by the date its claim's rounding goes by, added up; a boundary whose percent is
     * 0.00 adds nothing. 0.00 when not a full 30 days overdue.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate roundsBy) {
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
        RoundingMode rounding = rounding(roundsBy);
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = settings.latePct(dueBy.plusDays(n * LATE_PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(RateService.due(figure.add(charge), pct, rounding));
            }
        }
        return charge;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates for each grade on a sheet, each from its from-date, and the due a rate makes of an amount. */
@Service
public class RateService {

    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, ApplicationEventPublisher events) {
        this.rollup = rollup;
        this.rates = rates;
        this.sheets = sheets;
        this.events = events;
    }

    /** The sheet's rates by grade, each grade's earliest first (one with no from-date before all). */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetId(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate::getFromDate,
                        Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The sheet's rates with its today, dated settings and policy date, to find the rate in force and the live due on any date. */
    @Transactional(readOnly = true)
    public RateTable table(String sheetId) {
        return new RateTable(list(sheetId), sheets.today(sheetId), sheets.settings(sheetId),
                sheets.policyDate(sheetId));
    }

    /**
     * Set a grade's rate from a from-date (null: from the beginning of time) through a to-date (null: no
     * end), replacing the one it had from that date.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        sheets.load(sheetId, user);
        BigDecimal scaled = pct.setScale(2, RoundingMode.HALF_UP);
        Rollup.Figures before = rollup.figures(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, scaled));
        } else {
            rate.setPct(scaled);
            rate.setToDate(to);
            rates.flush();
        }
        events.publishEvent(new RateChanged(sheetId, user, grade, scaled, from, to));
        rollup.changed(sheetId, user, before);
        return rate;
    }

    /** An amount times a percent, divided by 100, rounded as given to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
        return pct == null ? null : amount.multiply(pct).divide(HUNDRED).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A sheet's rate for a grade (A, B or C): a percent with two decimals, in force from its from-date,
 * or from the beginning of time when it has none, through its to-date when it has one.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    /** The first date the rate applies to; null when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last date the rate applies to; null when it has no end. */
    @Column(name = "to_date")
    private LocalDate toDate;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;

/** Which grade is in force on a date. */
@FunctionalInterface
public interface Grades {

    /** The grade in force on the date. */
    String on(LocalDate date);
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * A sheet's dated settings: the value of each in force on a date is the one with the latest from-date on
 * or before it (a value with no from-date applying from the beginning of time); before every from-date,
 * and where that value was saved blank, the sheet's starting value (1.00 for the floor, 0.00 for the late
 * percent, 14 days for the terms; none for a grade's grace days, the clerk limit, the cap, the proof threshold, a grade's proof threshold and the note threshold; the sheet's terms for a grade's own
 * terms).
 */
public record DatedSettings(List<SheetSetting> values) {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String TERMS = "terms";

    public static final String LATE_PCT = "late-pct";

    public static final String CAP = "cap";

    public static final String PROOF_THRESHOLD = "proof-threshold";

    public static final String NOTE_THRESHOLD = "note-threshold";

    /** A sheet with no value saved: every setting has its starting value on every date. */
    public static final DatedSettings NONE = new DatedSettings(List.of());

    public static final String GRACE = "grace";

    /** The key of a grade's grace days: grace-A, grace-B or grace-C. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /** The key of a grade's proof threshold: proof-threshold-A, proof-threshold-B or proof-threshold-C. */
    public static String gradeProofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key's value in force on the date as written; empty when none is (or it was saved blank). */
    public Optional<String> on(String key, LocalDate date) {
        return values.stream()
                .filter(v -> v.getKey().equals(key))
                .filter(v -> v.getFromDate() == null || !v.getFromDate().isAfter(date))
                .max(Comparator.comparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(SheetSetting::getValue);
    }

    /** The least live due a claim dated on the date has. */
    public BigDecimal floor(LocalDate date) {
        return on(FLOOR, date).map(BigDecimal::new).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The percent an overdue claim gains of its figure for a 30-day boundary past its due-by falling on the date. */
