package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.SheetPasts;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.statement.DayEnds;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
 * today. The real clock is read only to start a new sheet's today; everything else that depends
 * on the date asks {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final Rollup rollup;
    private final DayEnds dayEnds;
    private final SheetPasts pasts;
    private final ApplicationEventPublisher events;
    private final Clock clock = Clock.systemDefaultZone();

    public SheetService(SheetRepository sheets, SheetSettingRepository settings, Rollup rollup, DayEnds dayEnds,
            SheetPasts pasts, ApplicationEventPublisher events) {
        this.dayEnds = dayEnds;
        this.pasts = pasts;
        this.sheets = sheets;
        this.settings = settings;
        this.rollup = rollup;
        this.events = events;
    }

    public Sheet load(String id, String user) {
        try {
            return loadOrCreate(id, user);
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: theirs is the one.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }

    /** The sheet as it stands; refused (404) when it was never loaded. */
    public Sheet get(String id) {
        return sheets.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet"));
    }

    /** The sheet's dated settings: the floor, late percent, terms, clerk limit and cap in force on any date. */
    public DatedSettings settings(String id) {
        return new DatedSettings(settings.findBySheetId(id));
    }

    /** The sheet's policy date as set; null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String id) {
        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
    }

    /** The sheet's period numbering from as set; null when blank (off). */
    public LocalDate periodNumberingFrom(String id) {
        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
    }

    /** The sheet's entry date as set; null when blank (off). */
    public LocalDate entryDate(String id) {
        return sheets.findById(id).map(Sheet::getEntryDate).orElse(null);
    }

    /** The date a new claim takes when none is given: the sheet's entry date while set, else its today. */
    public LocalDate claimDate(String id) {
        LocalDate entry = entryDate(id);
        return entry != null ? entry : today(id);
    }

    /** The sheet's grace days as set; null when blank (off). */
    public Integer graceDays(String id) {
        return sheets.findById(id).map(Sheet::getGraceDays).orElse(null);
    }

    /** Whether the sheet is archived: every change to it is refused. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** The sheet's today: the date to use for every decision and default date on the sheet. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
     * at the same moment wait on each other, so no number is given twice or skipped.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.bumpClaimNumber(id) != 1) {
            throw new IllegalStateException("No such sheet " + id);
        }
        return sheets.lastClaimNumber(id);
    }

    /**
     * Take the sheet's next settle batch number (1, 2, ...); two bulk settles at the same moment wait on each
     * other, so no number is given twice or skipped.
     */
    @Transactional
    public int nextSettleBatch(String id) {
        if (sheets.bumpSettleBatch(id) != 1) {
            throw new IllegalStateException("No such sheet " + id);
        }
        return sheets.lastSettleBatch(id);
    }

    /** The number of the sheet's last settle batch; 0 when there has been none (or no such sheet). */
    public int lastSettleBatch(String id) {
        Integer last = sheets.lastSettleBatch(id);
        return last == null ? 0 : last;
    }

    /**
     * Change the sheet's today, starting the sheet if it was never loaded. The change has no audit
     * line of its own, only what follows from it ({@link TodayChanged}: the periods past their grace
     * days are closed) and then the figures it moves. The sheet as it stands is first written down as at
     * the end of the today it leaves (see {@link DayEnds} and {@link SheetPasts}), and everyone's due-total
     * on it is announced first ({@link DaySnapshot}).
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        Rollup.Figures before = rollup.figures(id);
        if (!today.equals(sheet.getToday())) {
            events.publishEvent(new DaySnapshot(id, user, sheet.getToday(), List.copyOf(before.people().values())));
            dayEnds.record(id, sheet.getToday());
            pasts.record(id, sheet.getToday());
        }
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.changed(id, user, before);
        return saved;
    }

    private Sheet loadOrCreate(String id, String user) {
        return sheets.findById(id)
                .orElseGet(() -> sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock))));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Holds;

/**
 * A person on a sheet, with a name, their own terms (null: none) and their grades (A, B or C), each from a date (see {@link #gradeOn}), the date they are retired from (null while
 * not retired), their holds (see {@link #heldOn}) and the version it was last saved at.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    @Column(name = "terms")
    private Integer terms;

    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC")
    private List<HoldSpan> holds = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public long getVersion() {
        return version;
    }

    /**
     * The grade in force on the date: the one whose from-date is the latest on or before it, the first
     * grade (no from-date) applying from the beginning of time.
     */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(GradeFrom::getGrade).orElse(null);
    }

    /** The grades the person was given, each from its date. */
    public List<GradeFrom> getGrades() {
        return List.copyOf(grades);
    }

    /** Record the grade from the date, keeping the others; one already recorded from that date is replaced. */
    public void gradeFrom(String grade, LocalDate from) {
        grades.removeIf(g -> g.getFromDate() != null && Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(grade, from));
    }

    /** The person's own terms in days, in force on every date; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds, earliest from-date first. */
    public List<HoldSpan> getHolds() {
        return holds.stream().sorted(Comparator.comparing(HoldSpan::getFromDate)).toList();
    }

    /** Whether a hold covers the date: their OPEN claims dated then count in no live total. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Add a hold from a date to an optional date, keeping the others. */
    public void hold(LocalDate from, LocalDate to) {
        holds.add(new HoldSpan(from, to));
    }

    /** Whether the retirement date is reached on the sheet's today: on or after it. */
    public boolean retiredOn(LocalDate today) {
        return retiredFrom != null && !today.isBefore(retiredFrom);
    }

    /** The person's holds and retirement, as they leave claims out of the live totals. */
    public Holds leaves() {
        return new Holds() {
            @Override
            public boolean on(LocalDate date) {
                return heldOn(date);
            }

            @Override
            public boolean retiredOn(LocalDate today) {
                return Person.this.retiredOn(today);
            }
        };
    }

    /** Whether a retirement date is set: retired at once, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people on a sheet: listed in the order they were added, added and edited one at a time;
 * an edit made from a version someone else has saved since is refused. A person can be retired from a
 * date; no claim dated after it can then be added for them. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetService sheets,
            SheetRepository sheetRows, Rollup rollup, ApplicationEventPublisher events) {
        this.patrons = patrons;
        this.sheetRows = sheetRows;
        this.rollup = rollup;
        this.people = people;
        this.sheets = sheets;
        this.events = events;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional(readOnly = true)
    public Person get(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Person added = new Person(sheetId, trimmed, grade);
        added.setTerms(terms);
        added.setContact(contact);
        Person person = people.saveAndFlush(added);
        events.publishEvent(new PersonChanged("PERSON_ADDED", sheetId, user, trimmed, grade,
                terms == null ? null : terms.toString(), contact));
        rollup.changed(sheetId, user, before);
        return person;
    }

    /**
     * Save the person's name and record the grade from a date (none: the sheet's today), keeping the
     * grades already recorded; a grade left as the row showed it (in force on the sheet's today) with no
     * date records nothing. The person's own terms and contact are set to those given (null: none); a contact
     * another person on the sheet has is refused. The edit names the grade in force on the sheet's today after
     * it and, when they changed, the terms and the contact.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, Long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (version != null && version != person.getVersion()) {
            throw edited();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, personId)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.figures(sheetId);
        person.setName(trimmed);
        LocalDate today = sheets.today(sheetId);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
        }
        String termsChange = Objects.equals(terms, person.getTerms()) ? null : terms == null ? "" : terms.toString();
        person.setTerms(terms);
        String contactChange = Objects.equals(contact, person.getContact()) ? null : contact == null ? "" : contact;
        person.setContact(contact);
        people.flush();
        events.publishEvent(new PersonChanged("PERSON_EDITED", sheetId, user, trimmed, person.gradeOn(today),
                termsChange, contactChange));
        rollup.changed(sheetId, user, before);
        return person;
    }

    /**
     * Retire the person from a date; a date left out takes the sheet's today. Once the sheet's today reaches
     * it, their OPEN and PENDING claims not bound by a statement leave the live totals, so the figures it
     * moves are announced. The sheet stays locked
     * until the change commits, so a claim added meanwhile is checked against the new date.
     */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        sheetRows.lockById(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        Rollup.Figures before = rollup.figures(sheetId);
        person.setRetiredFrom(on);
        people.flush();
        events.publishEvent(new PersonRetired(sheetId, user, person.getName(), on));
        rollup.changed(sheetId, user, before);
        return person;
    }

    /**
     * Add a hold on the person from a date (none: the sheet's today) to an optional date, keeping their
     * other holds and moving the figures their OPEN claims dated within it count in. Refused when the
     * to-date is before the from-date. Takes turns with claim changes on the sheet.
     */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        sheetRows.lockById(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        person.hold(on, to);
        people.flush();
        events.publishEvent(new PersonHeld(sheetId, user, person.getName(), on));
        rollup.changed(sheetId, user, before);
        return person;
    }

    /** The ids of each person's patrons on the sheet, by person id, in the order they were named. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronsBySheet(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
                Patron::getPersonId, Collectors.mapping(Patron::getPatronId, Collectors.toList())));
    }

    /** The ids of the person's patrons, in the order they were named. */
    @Transactional(readOnly = true)
    public List<Long> patrons(String sheetId, long personId) {
        return patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId).stream()
                .map(Patron::getPatronId).toList();
    }

    /**
     * The person names another person on the sheet as their patron. Naming themselves, someone not on
     * the sheet or someone already their patron is refused. Takes turns with other changes on the sheet.
     */
    @Transactional
    public Person addPatron(String sheetId, String user, long personId, long patronId) {
        sheetRows.lockById(sheetId);
        Person person = get(sheetId, personId);
        if (patronId == personId) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron");
        }
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "No such person"));
        if (patrons.existsByPersonIdAndPatronId(personId, patronId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
        }
        patrons.saveAndFlush(new Patron(sheetId, personId, patronId));
        events.publishEvent(new PatronAdded(sheetId, user, person.getName(), patron.getName()));
        return person;
    }

    /** Someone else saved the person after the editor loaded them. */
    public static ResponseStatusException edited() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since loaded");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use");
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person from a date to a date (both included); no to-date: open-ended. */
@Embeddable
public class HoldSpan {

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected HoldSpan() {
    }

    public HoldSpan(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the hold covers the date: on or after its from-date and, when it has one, on or before its to-date. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(fromDate) && (toDate == null || !date.isAfter(toDate));
    }
}
