package net.officefloor.hq.app.rollup;


/**
 * The figures of a sheet: each person's claimed, due-total and overdue-total, and the sheet's
 * claimed-total, due-total (a person showing n/a is skipped) and overdue-total, the last two leaving out the
 * single highest and single lowest person's figure when three or more people have one. A change takes the figures before it and, once done,
 * announces the ones it moved. Reads the store directly, within the change's own transaction.
 */
@Service
public class Rollup {

    /**
     * A person's figures as shown: claimed, due-total ({@code n/a} when there is none), and overdue-total
     * (the sum of the due figures of their overdue claims that count).
     */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {

        boolean sameFigures(PersonFigures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The sheet's claimed-total, due-total and overdue-total as shown. */
    public record Totals(String claimed, String dueTotal, String overdueTotal) {
    }

    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, Totals totals) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final ApplicationEventPublisher events;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, ApplicationEventPublisher events) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.events = events;
    }

    /** The sheet's figures now. */
    public Figures figures(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? LocalDate.now() : sheet.getToday();
        RateTable table = new RateTable(rates.findBySheetId(sheetId), today,
                new DatedSettings(settings.findBySheetId(sheetId)), sheet == null ? null : sheet.getPolicyDate());
        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, PersonFigures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
            BigDecimal claimed = theirs.stream().filter(c -> Dues.counts(c, person.leaves(), today)).map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO, BigDecimal::add);
            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person.leaves());
            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, person::gradeOn, table, person.leaves()), table);
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue.setScale(2, RoundingMode.HALF_UP));
            if (due != null) {
                dues.add(due.setScale(2, RoundingMode.HALF_UP));
            }
            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
                    due == null ? "n/a" : money(due), money(overdue)));
        }
        return new Figures(figures, new Totals(money(claimedTotal), money(trimmedSum(dues)), money(trimmedSum(overdues))));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
    }

    /**
     * Announce the figures the change moved since {@code before}: each person whose figures changed (one
     * who did not exist before counting as changed), then the totals when they changed. Nothing when no
     * figure moved.
     */
    public void changed(String sheetId, String user, Figures before) {
        Figures after = figures(sheetId);
        List<PersonFigures> moved = new ArrayList<>();
        after.people().forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                moved.add(now);
            }
        });
        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
        if (!moved.isEmpty() || totals != null) {
            events.publishEvent(new RollupChanged(sheetId, user, moved, totals));
        }
    }

    private static String money(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }
}
package net.officefloor.hq.app.period;


/**
 * A period on a sheet: a name unique on the sheet, and a from and to date, both inclusive. Once closed or
 * soft-closed, its due-total is the one fixed then; claims due by a date inside a soft-closed one can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed, but claims due by a date inside it can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    @Column(name = "closed_total", precision = 14, scale = 2)
    private BigDecimal closedTotal;

    /** Per person id, the person's due-total fixed when the period was closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean isFixed() {
        return closed || softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    /** Close the period, fixing each person's due-total for it and its own, their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        close(personTotals, false);
    }

    /**
     * Close the period, or soft-close it, fixing each person's due-total for it and its own, their sum. A
     * soft-closed period still takes changes to the claims due by a date inside it.
     */
    public void close(Map<Long, BigDecimal> personTotals, boolean soft) {
        this.closed = !soft;
        this.softClosed = soft;
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
    }

    /** Whether the date falls in the period, its from and to date included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether the period shares a date with the one from {@code from} to {@code to}. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !from.isAfter(toDate) && !to.isBefore(fromDate);
    }
}
package net.officefloor.hq.app.period;


/**
 * The periods on a sheet, earliest first: none share a name (case ignored) or a date. A closed period
 * keeps the due-total it had when closed, and no claim due by a date inside it can change.
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateService rates;
    private final AccessService access;
    private final ApplicationEventPublisher events;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows,
            ClaimRepository claims, PersonRepository people, RateService rates, AccessService access,
            ApplicationEventPublisher events) {
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.access = access;
        this.events = events;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /**
     * Add a period from {@code from} to {@code to}, both inclusive. Refused when the name is taken on the
     * sheet, the to-date is before the from-date, or it shares a date with another period. Two users adding
     * one at the same moment wait on each other, so no two overlap.
     */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (to.isBefore(from)) {
            throw new PeriodRefused("The to-date is before the from-date.");
        }
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw new PeriodRefused("That period name is already in use on this sheet.");
        }
        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodRefused("The period overlaps another period.");
        }
        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to));
        events.publishEvent(new PeriodAdded(sheetId, user, name, from, to));
        return period;
    }

    /**
     * Generate one period per calendar month from the from-date's month to the to-date's month, each running
     * from the first to the last day of its month and named yyyy-mm. A month whose name is already a period on
     * the sheet, or whose days overlap one, is left out; the others are still made. Refused when the to-date is
     * before the from-date. Returns the periods made, earliest first.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (to.isBefore(from)) {
            throw new PeriodRefused("The to-date is before the from-date.");
        }
        List<Period> existing = new ArrayList<>(list(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(name) || p.overlaps(first, last))) {
                continue;
            }
            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
            events.publishEvent(new PeriodAdded(sheetId, user, name, first, last));
            existing.add(period);
            made.add(period);
        }
        return made;
    }

    /**
     * Close a period, fixing each person's due-total for it, for every person on the sheet, and its own, their sum: the due figures of the claims due by a date inside it that counted (OPEN, PENDING and SETTLED,
     * but not an unbound OPEN claim dated within a hold of its person, nor a deferred one) at the end of its last day,
     * see {@link Dues#countsAsOf}, added up per person. A soft-closed period is closed with its figures fixed
     * afresh. Refused when it is already closed, or for a role the sheet's
     * permission matrix does not allow to close. Takes turns with claim changes on the
     * sheet, so the total fixed is the one the claims had at that moment.
     */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.CLOSE)) {
            throw new PeriodRefused("Your role may not close a period on this sheet.");
        }
        if (period.isClosed()) {
            throw new PeriodRefused("The period is already closed.");
        }
        fix(sheetId, user, period, false, false);
        return period;
    }

    /**
     * Soft-close an open period: its figures are fixed as a close fixes them, but claims due by a date inside it can
     * still be added, edited, opened, settled and voided. Refused when it is already closed or soft-closed, or
     * for a role the sheet's permission matrix does not allow to close.
     */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.CLOSE)) {
            throw new PeriodRefused("Your role may not close a period on this sheet.");
        }
        if (period.isClosed()) {
            throw new PeriodRefused("The period is already closed.");
        }
        if (period.isSoftClosed()) {
            throw new PeriodRefused("The period is already soft-closed.");
        }
        fix(sheetId, user, period, false, true);
        return period;
    }

    /**
     * When the sheet's today is changed and it has grace days, close every open period (neither closed nor
     * soft-closed) whose to-date plus the grace days is before the new today, in order of their to-dates, each as a close by hand would.
     */
    @EventListener
    @Transactional
    public void on(TodayChanged e) {
        Integer grace = sheets.graceDays(e.sheetId());
        if (grace == null) {
            return;
        }
        sheetRows.lockById(e.sheetId());
        list(e.sheetId()).stream()
                .filter(p -> !p.isFixed() && p.getToDate().plusDays(grace).isBefore(e.today()))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> fix(e.sheetId(), e.user(), p, true, false));
    }

    /** Fix the period's due-totals as of the end of its last day and close it, or soft-close it. */
    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        RateTable table = rates.table(sheetId);
        Map<Long, BigDecimal> totals = new HashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> period.contains(c.getDueBy())
                        && Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
                .forEach(c -> {
                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
                    if (due != null) {
                        totals.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
        period.close(totals, soft);
        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
        periods.flush();
        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
    }

    /**
     * Reopen a closed or soft-closed period: its due-total is live again, the current figures of the claims
     * due by a date inside it. Refused unless the sheet's permission matrix allows the user's role (a steward, unless
     * set), and when the period is neither closed nor soft-closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.REOPEN)) {
            throw new PeriodRefused("Your role may not reopen a period on this sheet.");
        }
        if (!period.isFixed()) {
            throw new PeriodRefused("The period is not closed.");
        }
        period.reopen();
        periods.flush();
        events.publishEvent(new PeriodReopened(sheetId, user, period.getName()));
        return period;
    }

    /** The closed period whose dates contain the date, if any. */
    @Transactional(readOnly = true)
    public Optional<Period> closedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
    }

    /** The soft-closed period whose dates contain the date, if any. */
    @Transactional(readOnly = true)
    public Optional<Period> softClosedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.isSoftClosed() && p.contains(date)).findFirst();
    }

    /**
     * Refuse a change to a claim due by any of the dates when a closed period contains it. Holds the
     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
     */
    @Transactional
    public void requireOpen(String sheetId, LocalDate... dates) {
        sheetRows.lockById(sheetId);
        for (LocalDate date : dates) {
            closedOn(sheetId, date).ifPresent(p -> {
                throw new ClosedPeriodRefused(p.getName());
            });
        }
    }
}

