package net.officefloor.hq.app.statement;


/**
 * The statements taken for the people on a sheet. Taking one records the person's due-total and
 * binds each of their claims that counts to the figure it has then (without its late charge, which
 * keeps following the sheet's today); a claim that does not count is released to its live figure. A
 * statement can be taken as of a date gone by, from the sheet as it stood at the end of that date.
 * A steward can cancel a person's last statement: the claims it bound are released to their live
 * figures (a figure an earlier statement bound is not restored).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateService rates;
    private final Rollup rollup;
    private final AccessService access;
    private final DayEnds dayEnds;
    private final ApplicationEventPublisher events;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            RateService rates, Rollup rollup, AccessService access, DayEnds dayEnds,
            ApplicationEventPublisher events) {
        this.dayEnds = dayEnds;
        this.access = access;
        this.rollup = rollup;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.events = events;
    }

    /** Every person's statements on the sheet, by person. */
    @Transactional(readOnly = true)
    public Map<Long, Statements> bySheet(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId,
                        Collectors.collectingAndThen(Collectors.toList(), Statements::of)));
    }

    @Transactional(readOnly = true)
    public Statements forPerson(String sheetId, long personId) {
        return Statements.of(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
    }

    /** Take a statement for the person as of the sheet's today. */
    @Transactional
    public void take(String sheetId, String user, long personId) {
        take(sheetId, user, personId, null);
    }

    /**
     * Take a statement for the person as of a date on or before the sheet's today (null: as of now). Their
     * claims that counted at the end of that date are bound to the figures they had then, with that date
     * standing in for the sheet's today, and every other claim of theirs is released; the statement is
     * dated that date and records their due-total then. A date gone by takes the sheet as it stood at the
     * end of it (see {@link DayEnds}): refused when the date is after the sheet's today, or when the person
     * was not on the sheet by then.
     */
    @Transactional
    public void take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RateTable table = rates.table(sheetId);
        LocalDate on = asOf == null ? table.today() : asOf;
        if (on.isAfter(table.today())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A statement cannot be taken as of a date after today");
        }
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        Person then;
        Map<Long, Claim> claimsThen;
        if (on.isBefore(table.today())) {
            DayEnds.SheetThen sheetThen = dayEnds.asOf(sheetId, on)
                    .filter(t -> t.people().containsKey(personId))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
                            "The person was not on the sheet by that date"));
            then = sheetThen.people().get(personId);
            claimsThen = sheetThen.claimsOf(personId);
            table = sheetThen.table();
        } else {
            then = person;
            claimsThen = new LinkedHashMap<>();
            theirs.forEach(c -> claimsThen.put(c.getId(), c));
        }
        Rollup.Figures before = rollup.figures(sheetId);
        BigDecimal dueTotal = Dues.total(then::gradeOn, List.copyOf(claimsThen.values()), table, then.leaves());
        int counting = 0;
        for (Claim claim : theirs) {
            Claim stood = claimsThen.get(claim.getId());
            if (stood != null && Dues.counts(stood, then.leaves(), table.today())) {
                claim.bind(Dues.base(stood, then::gradeOn, table));
                counting++;
            } else {
                claim.unbind();
            }
        }
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, on, dueTotal, counting));
        events.publishEvent(new StatementTaken(sheetId, user, person.getName(), dueTotal, counting, asOf));
        rollup.changed(sheetId, user, before);
    }

    /** Cancel the person's last statement; only a steward may, and only while the person has one. */
    @Transactional
    public void cancel(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
        }
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (taken.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Statement last = taken.get(taken.size() - 1);
        for (Claim claim : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (claim.isStated()) {
                claim.unbind();
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        events.publishEvent(new StatementCancelled(sheetId, user, person.getName(), last.getDueTotal()));
        rollup.changed(sheetId, user, before);
    }
}
package net.officefloor.hq.app.statement;


/** A person's statements as shown: how many were taken, and the last one's due-total and date (null with none). */
public record Statements(int count, BigDecimal lastDueTotal, LocalDate lastDate) {

    public static final Statements NONE = new Statements(0, null, null);

    /** A person's statements, in the order taken. */
    public static Statements of(List<Statement> taken) {
        if (taken.isEmpty()) {
            return NONE;
        }
        Statement last = taken.get(taken.size() - 1);
        return new Statements(taken.size(), last.getDueTotal(), last.getTakenOn());
    }
}
package net.officefloor.hq.app.statement;


/**
 * The sheet as it stood at the end of each day it had as its today: when its today moves on, everything
 * its figures are made from (its claims, people, rates, dated settings and policy date) is written down
 * as it is then. The sheet at the end of a date gone by is the last one written for a day on or before
 * it: every change made while its today was on or before that date, and none made later.
 */
@Service
public class DayEnds {

    record ClaimRow(long id, long personId, BigDecimal amount, LocalDate date, ClaimStatus status,
            LocalDate correctsDate, LocalDate dueBy, LocalDate deferredUntil, BigDecimal settledDue, boolean stated,
            BigDecimal statedDue) {
    }

    record GradeRow(String grade, LocalDate from) {
    }

    record HoldRow(LocalDate from, LocalDate to) {
    }

    record PersonRow(long id, String name, List<GradeRow> grades, List<HoldRow> holds, LocalDate retiredFrom) {
    }

    record RateRow(String grade, LocalDate from, LocalDate to, BigDecimal pct) {
    }

    record SettingRow(String key, LocalDate from, String value) {
    }

    record State(LocalDate policyDate, List<RateRow> rates, List<SettingRow> settings, List<PersonRow> people,
            List<ClaimRow> claims) {
    }

    /**
     * The sheet as it stood at the end of a date: its rates and settings with that date as their today,
     * its people by id and each person's claims by id (newest first), none of them kept in the store.
     */
    public record SheetThen(RateTable table, Map<Long, Person> people, Map<Long, Map<Long, Claim>> claims) {

        /** The person's claims then, by id; none when they had none. */
        public Map<Long, Claim> claimsOf(long personId) {
            return claims.getOrDefault(personId, Map.of());
        }
    }

    private final DayEndRepository dayEnds;
    private final SheetRepository sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SheetSettingRepository settings;
    private final JsonMapper json;

    public DayEnds(DayEndRepository dayEnds, SheetRepository sheets, ClaimRepository claims,
            PersonRepository people, RateRepository rates, SheetSettingRepository settings, JsonMapper json) {
        this.dayEnds = dayEnds;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.json = json;
    }

    /** Write the sheet down as it stands now, as at the end of the day given (the today it is leaving). */
    @Transactional
    public void record(String sheetId, LocalDate day) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        State state = new State(sheet == null ? null : sheet.getPolicyDate(),
                rates.findBySheetId(sheetId).stream()
                        .map(r -> new RateRow(r.getGrade(), r.getFromDate(), r.getToDate(), r.getPct())).toList(),
                settings.findBySheetId(sheetId).stream()
                        .map(s -> new SettingRow(s.getKey(), s.getFromDate(), s.getValue())).toList(),
                people.findBySheetIdOrderByIdAsc(sheetId).stream()
                        .map(p -> new PersonRow(p.getId(), p.getName(),
                                p.getGrades().stream().map(g -> new GradeRow(g.getGrade(), g.getFromDate())).toList(),
                                p.getHolds().stream().map(h -> new HoldRow(h.getFromDate(), h.getToDate())).toList(),
                                p.getRetiredFrom()))
                        .toList(),
                claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                        .map(c -> new ClaimRow(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(), c.getStatus(),
                                c.getCorrectsDate(), c.getDueBy(), c.getDeferredUntil(), c.getSettledDue(),
                                c.isStated(), c.getStatedDue()))
                        .toList());
        dayEnds.saveAndFlush(new DayEnd(sheetId, day, json.writeValueAsString(state)));
    }

    /** The sheet as it stood at the end of the date, with that date as its today; empty when none was written by then. */
    @Transactional(readOnly = true)
    public Optional<SheetThen> asOf(String sheetId, LocalDate date) {
        return dayEnds.findFirstBySheetIdAndEndedOnLessThanEqualOrderByIdDesc(sheetId, date)
                .map(d -> then(sheetId, date, json.readValue(d.getState(), State.class)));
    }

    private static SheetThen then(String sheetId, LocalDate date, State state) {
        RateTable table = new RateTable(
                state.rates().stream().map(r -> new Rate(sheetId, r.grade(), r.from(), r.to(), r.pct())).toList(),
                date,
                new DatedSettings(state.settings().stream()
                        .map(s -> new SheetSetting(sheetId, s.key(), s.from(), s.value())).toList()),
                state.policyDate());
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (PersonRow row : state.people()) {
            byId.put(row.id(), person(sheetId, row));
        }
        Map<Long, Map<Long, Claim>> claimsByPerson = new LinkedHashMap<>();
        for (ClaimRow row : state.claims()) {
            claimsByPerson.computeIfAbsent(row.personId(), k -> new LinkedHashMap<>()).put(row.id(), claim(sheetId, row));
        }
        return new SheetThen(table, byId, claimsByPerson);
    }

    private static Person person(String sheetId, PersonRow row) {
        GradeRow first = row.grades().stream().filter(g -> g.from() == null).findFirst()
                .orElse(row.grades().isEmpty() ? new GradeRow(null, null) : row.grades().get(0));
        Person person = new Person(sheetId, row.name(), first.grade());
        row.grades().stream().filter(g -> g != first).forEach(g -> person.gradeFrom(g.grade(), g.from()));
        row.holds().forEach(h -> person.hold(h.from(), h.to()));
        person.setRetiredFrom(row.retiredFrom());
        return person;
    }

    private static Claim claim(String sheetId, ClaimRow row) {
        Claim claim = new Claim(sheetId, row.personId(), row.amount(), row.date(), "", null);
        claim.setStatus(row.status());
        claim.setCorrectsDate(row.correctsDate());
        claim.setDueBy(row.dueBy());
        claim.setDeferredUntil(row.deferredUntil());
        claim.setSettledDue(row.settledDue());
        if (row.stated()) {
            claim.bind(row.statedDue());
        }
        return claim;
    }
}
package net.officefloor.hq.app.holiday;


/**
 * The holidays on a sheet, earliest first; no date is on it twice. A claim's due-by, when it is fixed as the
 * claim is added, is the terms-th business day after its date, skipping weekends and the holidays on the sheet
 * then (see {@link #dueBy}). A holiday added later fixes again the due-by of every claim on the sheet that is
 * not SETTLED or VOID and is due on or after it, from the claim's date with the terms it was fixed with.
 */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ClaimRepository claims;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows,
            ClaimRepository claims, Rollup rollup, ApplicationEventPublisher events) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.claims = claims;
        this.rollup = rollup;
        this.events = events;
    }

    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    }

    /**
     * Add a holiday, fixing again the due-by of each claim not SETTLED or VOID due on or after it; refused when
     * the date is already on the sheet's list.
     */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (holidays.existsBySheetIdAndDay(sheetId, date)) {
            throw new HolidayRefused("That date is already a holiday on this sheet.");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() != ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.VOID
                    && !claim.getDueBy().isBefore(date)) {
                claim.setDueBy(businessDaysAfter(claim.getDate(), claim.getTerms(), days));
            }
        }
        claims.flush();
        events.publishEvent(new HolidayAdded(sheetId, user, date));
        rollup.changed(sheetId, user, before);
        return saved;
    }

    /** The due-by of a claim dated {@code date} with these terms, see {@link #businessDaysAfter}. */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
        return businessDaysAfter(date, terms, days);
    }

    /**
     * The {@code terms}-th business day after the date, counting forward from the day after it and skipping
     * every Saturday, Sunday and holiday given; the date itself when the terms are 0 or less.
     */
    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate day = date;
        for (int left = terms; left > 0; ) {
            day = day.plusDays(1);
            if (businessDay(day, holidays)) {
                left--;
            }
        }
        return day;
    }

    private static boolean businessDay(LocalDate day, Set<LocalDate> holidays) {
        DayOfWeek dow = day.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    }
}

