package net.officefloor.hq.app.claim;


/**
 * Moves a selection of claims to another person together, in list order: the people in the order they
 * were added, each person's newest claim first. Each claim is moved on its own by the rules of moving
 * one, so one that cannot be moved is refused and left as it is while the rest go through; one already
 * the person's is moved to them again.
 */
@Service
public class BulkReassignService {

    public record Result(int reassigned, int refused) {
    }

    private final ClaimService claims;
    private final SelectedClaims selected;
    private final AccessService access;

    public BulkReassignService(ClaimService claims, SelectedClaims selected, AccessService access) {
        this.access = access;
        this.claims = claims;
        this.selected = selected;
    }

    public Result reassign(String sheetId, String user, Set<Long> claimIds, long toPersonId) {
        if (access.isArchived(sheetId) || access.isViewer(sheetId, user)) {
            return new Result(0, claimIds.size()); // an archived sheet, or a viewer, changes nothing: every one refused
        }
        int reassigned = 0;
        for (Claim c : selected.inListOrder(sheetId, claimIds)) {
            try {
                claims.reassign(sheetId, user, c.getId(), toPersonId, true);
                reassigned++;
            } catch (ResponseStatusException | ClosedPeriodRefused refused) {
                // refused: left as it is
            }
        }
        return new Result(reassigned, claimIds.size() - reassigned);
    }
}
package net.officefloor.hq.app.person;


/**
 * Gives a selection of people a grade from a date together, in list order: the people in the order
 * they were added. Each person is edited on their own, exactly as the person form would (their name
 * and own terms kept, no version check), so one that cannot be edited is left as they are while the
 * rest go through.
 */
@Service
public class BulkGradeService {

    public record Result(int graded) {
    }

    private final PersonService people;
    private final AccessService access;

    public BulkGradeService(PersonService people, AccessService access) {
        this.people = people;
        this.access = access;
    }

    public Result grade(String sheetId, String user, Set<Long> personIds, String grade, LocalDate from) {
        if (access.isArchived(sheetId) || access.isViewer(sheetId, user)) {
            return new Result(0); // an archived sheet, or a viewer, changes nothing: every one refused
        }
        int graded = 0;
        for (Person p : people.list(sheetId)) {
            if (!personIds.contains(p.getId())) {
                continue;
            }
            try {
                people.edit(sheetId, user, p.getId(), null, p.getName(), grade, from, p.getTerms(), p.getContact());
                graded++;
            } catch (ResponseStatusException refused) {
                // refused: left as they are
            }
        }
        return new Result(graded);
    }
}
package net.officefloor.hq.app.claim;


/**
 * The void reasons on a sheet, in the order they were added; no reason is on it twice. While the list is not
 * empty, a claim is voided only with a reason on it (see {@link #require}).
 */
@Service
public class VoidReasons {

    /** The longest a reason may be. */
    static final int REASON_MAX = 100;

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ApplicationEventPublisher events;

    public VoidReasons(VoidReasonRepository reasons, SheetService sheets, SheetRepository sheetRows,
            ApplicationEventPublisher events) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.events = events;
    }

    /** The reasons on the sheet, in the order they were added. */
